(this["webpackJsonpbrown-edu-orchestra"]=this["webpackJsonpbrown-edu-orchestra"]||[]).push([[37],{119:function(e,t,a){"use strict";a.r(t),a.d(t,"readingTime",(function(){return n})),a.d(t,"meta",(function(){return s})),a.d(t,"default",(function(){return h})),a.d(t,"tableOfContents",(function(){return c})),a.d(t,"frontMatter",(function(){return l}));var o=a(11),i=(a(2),a(1)),n={text:"3 min read",minutes:2.82,time:169200,words:564},s={title:"Soloist Spotlight: Lucas Sha ",subtitle:"Featuring Lucas Sha '27",author:{name:"Brendon Wen",uid:"brendonwen1",email:"brendon_wen@brown.edu",browndirectory:"4b41fe6d-c22c-4498-94f7-1af5b5a1fc59"},topic:"Blog",date:"2026-10-17",image:{url:"/images/uploads/lucas_sha_resized_800.jpg"},path:"/news/2026-10-17/soloist-spotlight-lucas-sha"},r={meta:s};function h(e){var t=e.components,a=Object(o.a)(e,["components"]);return Object(i.a)("wrapper",Object.assign({},r,a,{components:t,mdxType:"MDXLayout"}),Object(i.a)("p",null,"For Lucas Sha \u201927, what started as a fascination for Chopin Ballade recordings on YouTube will lead to his soloist performance of Franz Liszt\u2019s Piano Concerto No. 2 in A major, S. 125, with the Brown University Orchestra on Saturday, October 17, 2026."),Object(i.a)("p",null,"The senior, concentrating in Mathematics and Computer Science, began learning piano at 11, imploring his parents to enroll him for lessons. Since then, he\u2019s developed a deep appreciation for the Romantic Era, spearheaded by the likes of Liszt and Wagner. To ultimately perform the works of one of these giants warrants an exploration of human expressivity, which Sha readily accepts.\xa0"),Object(i.a)("p",null,"\u201cI simply, really am fascinated by this New German School of music that ","[","Liszt] was a part of\u2026 They espoused a similar philosophy, which was the integration of music with the other arts\u2014like the literary, visual, ","[","and] philosophical\u2014of humanity,\u201d Sha says, pointing to the development of music as a language of emotion."),Object(i.a)("p",null,"While both of Liszt\u2019s piano concerti carry an extroverted air of virtuosity, the second harps about his glory as a composer. Stitching the single-movement piece with intertwining variations on a theme, Liszt shepherds the listeners through a melodic transformation, or a metamorphosis."),Object(i.a)("p",null,"The woodwinds open with an intimate chorale that the piano embeds itself within. Then, the concerto dives into delicate introspection, agitated turmoil, and bel canto, ultimately arriving at a stalwart march echoing with triumph."),Object(i.a)("p",null,"Sha says he chose the concerto for two reasons: Liszt\u2019s revolutionary influence as a pianist and as a composer. \u201cHe was the one who basically set the tradition of the virtuoso pianist-composer\u2026 we owe the existence of pianist-composers like Rachmaninoff who came to Liszt and this legacy that he created.\u201d"),Object(i.a)("p",null,"Like many symphonic poems, Liszt\u2019s Piano Concerto No. 2 teases out as much human emotion as possible from every instrument in the ensemble to pull at our heartstrings. And the Hungarian composer isn\u2019t afraid to share the spotlight to do so."),Object(i.a)("p",null,"\u201cThis psychological element of coordination is totally different\u2026 because at the end of the day, there is a much wider range of color and sound that the orchestra makes,\u201d Sha says."),Object(i.a)("p",null,"Outside of playing the piano, Sha has thoroughly enjoyed studying mathematics at Brown, noting the subject has a unique beauty and many intriguing areas of focus. While he keeps academics separate from music, he finds that the two always seem to find a way back. Sha offers two bits of math-music trivia: \u201cThe great mathematician Johann Dirichlet was married to Mendelssohn\u2019s sister, Rebecca Mendelssohn. ","[","Moving] a few decades into the future, the great mathematician Rolf Nevanlinna was very close with Sibelius and described him as the greatest and most powerful figure that he had known in his life.\u201d"),Object(i.a)("p",null,"Sha also wishes to explore the cornerstone of musicianship that is composition. He attributes the greatness of performers he admires, such as Dinu Lipatti, to their commitment in the compositional process."),Object(i.a)("p",null,"In particular, Sha believes that composition helps musicians enhance the intentionality in their interpretations. Through practicing composition, Sha hopes to gain a \u201ccomposer\u2019s eye view,\u201d which would allow him to refine the collaborative interplay between the soloist and orchestra."),Object(i.a)("p",null,"\u201cIt\u2019s a richer experience because you have to really work through how to make the orchestra sound organic and integrated with your own solo playing, your own music,\u201d Sha says."))}h.isMDXComponent=!0;var c=function(){return[]},l={}}}]);
